arguments.argument:
if file_exists(global.load)
{
file_delete("tmp.trc")

open_file = file_bin_open(global.load, 0)
file_size = file_bin_size(open_file)

save_file = file_bin_open("tmp.trc", 1)

for(i=0; i!=file_size; i+=1)
{
file_bin_seek(open_file, i)
file_message = file_bin_read_byte(open_file)

file_bin_seek(save_file, i)
file_bin_write_byte(save_file, file_message)

if i=1117006
{
sk_cut_hex(sk_hex_conversion(real(obj_year.vares)))

file_bin_seek(save_file, i+1)
file_bin_write_byte(save_file, real(stringsrfg[0]))

file_bin_seek(save_file, i+2)
file_bin_write_byte(save_file, real(stringsrfg[1]))

i+=2
}
//년도 설정

if i=1117023
{
file_bin_seek(save_file, i+1)
file_bin_write_byte(save_file, real(obj_month.vares))

file_bin_seek(save_file, i+2)
file_bin_write_byte(save_file, real(obj_day.vares))
i+=2
}
//기타 설정

}
file_bin_close(open_file)
file_bin_close(save_file)

file_copy("tmp.trc", global.load)
file_delete("tmp.trc")

show_message('버젼변경 완료!요')

stringsrfg[0]=""
stringsrfg[1]=""
}
else{show_message('trc파일이 없습니다요'); game_end()}
